#!/usr/bin/env node
// Builds the Unpaged marketing site into dist/.
//
//   node site/build.mjs                          # uses site.config.json
//   SITE_URL=http://127.0.0.1:4400 node site/build.mjs
//
// Zero dependencies. Images in public/ are generated by tools/assets.mjs and committed.
// The support, privacy and terms pages are rendered from support.md, privacy-policy.md
// and EULA.md in the repository root, so the website and the App Store documents never drift apart.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { site as english } from './src/content.mjs';

const root = path.dirname(fileURLToPath(import.meta.url));
const repo = path.resolve(root, '..');
const out = path.join(root, 'dist');
const config = JSON.parse(fs.readFileSync(path.join(root, 'site.config.json'), 'utf8'));
const origin = (process.env.SITE_URL || config.siteUrl).replace(/\/+$/, '');
const base = new URL(`${origin}/`).pathname; // "/" or "/Ebooker/"
const asset = file => `${base}${file}`;
const e = s => String(s).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;');
// Headings carry a little inline markup (<em>, <br>, &nbsp;) from the content files, which are trusted source.
const rich = s => s;
const W = 720, H = 1564;

// ---------------------------------------------------------------- locales
const localeNames = { en: 'English', de: 'Deutsch', es: 'Español', fr: 'Français', it: 'Italiano', 'pt-br': 'Português (BR)' };
const htmlLang = code => (code === 'pt-br' ? 'pt-BR' : code);
const merge = (a, b) => {
  if (Array.isArray(b) || typeof b !== 'object' || b === null) return b;
  const o = { ...a };
  for (const [k, v] of Object.entries(b)) o[k] = k in o ? merge(o[k], v) : v;
  return o;
};
const locales = { en: english };
for (const code of Object.keys(localeNames).filter(c => c !== 'en')) {
  locales[code] = merge(english, (await import(path.join(root, 'src/i18n', `${code}.mjs`))).default);
}
const prefixOf = code => (code === 'en' ? '' : `${code}/`);

// ---------------------------------------------------------------- output
// Empty dist/ in place (keeps a local preview server's working directory valid).
fs.mkdirSync(out, { recursive: true });
for (const entry of fs.readdirSync(out)) fs.rmSync(path.join(out, entry), { recursive: true, force: true });
fs.cpSync(path.join(root, 'public'), out, { recursive: true });
fs.cpSync(path.join(root, 'src/style.css'), path.join(out, 'style.css'));
fs.cpSync(path.join(root, 'src/app.mjs'), path.join(out, 'app.mjs'));
for (const file of ['sky.css', 'sky.mjs']) fs.cpSync(path.join(root, 'src', file), path.join(out, file));
const written = [];
const write = (rel, html) => {
  const file = path.join(out, rel);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, html);
  written.push(file);
};

// ---------------------------------------------------------------- marks
// Vector redraw of the app icon: navy field, cream bookmark, amber playhead dot.
const logoMark = (cls = 'logo-mark') => `<svg class="${cls}" viewBox="0 0 1024 1024" aria-hidden="true"><rect width="1024" height="1024" rx="228" fill="#122231"/><path d="M387 121h250v639l-125-105-125 105Z" fill="#f4efe8"/><circle cx="512" cy="818" r="72" fill="#e49a21"/></svg>`;
fs.writeFileSync(path.join(out, 'img/favicon.svg'), logoMark('').replace(' class=""', ' xmlns="http://www.w3.org/2000/svg"').replace(' aria-hidden="true"', ''));
const arrow = `<svg class="i-arrow" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>`;
const sparkle = `<svg class="i-sparkle" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.5c.5 4.6 2.9 7 7.5 7.5-4.6.5-7 2.9-7.5 7.5-.5-4.6-2.9-7-7.5-7.5 4.6-.5 7-2.9 7.5-7.5Z"/><path d="M19 15.5c.2 1.8 1.1 2.8 3 3-1.9.2-2.8 1.1-3 3-.2-1.9-1.2-2.8-3-3 1.8-.2 2.8-1.2 3-3Z"/></svg>`;
const bookmarkGlyph = `<svg class="i-bookmark" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3h10v18l-5-4.2L7 21Z"/></svg>`;
// The live sky (src/sky.css, src/sky.mjs) sits behind the header and the first section. `strip` is the short header-only band.
const sky = (strip = false) => `<div class="sky${strip ? ' sky-strip' : ''}" aria-hidden="true"><div class="sky-stars"></div><div class="sky-sun"></div><div class="sky-moon"></div><canvas class="sky-canvas"></canvas><div class="sky-fog"></div><div class="sky-flash"></div><i class="sky-end"></i></div>`;
// Picks the daypart and weather before first paint, so dark skies never flash light text: a QA override,
// else this session's last sky (under 30 minutes old), else the clock. sky.mjs refines it.
const skyBoot = `<script>try{const r=document.documentElement,q=new URLSearchParams(location.search),s=JSON.parse(sessionStorage.getItem('unpaged-sky-state')||'null'),d=q.get('daypart'),w=q.get('sky'),f=s&&w!=='offline'&&Date.now()-s.at<18e5,n=new Date(),m=n.getHours()*60+n.getMinutes();r.dataset.daypart=/^(dawn|day|dusk|night)$/.test(d)?d:f?s.daypart:m<345||m>=1170?'night':m<435?'dawn':m<1080?'day':'dusk';r.dataset.weather=/^(clear|cloudy|fog|rain|snow|storm)$/.test(w)?w:f?s.weather:'clear'}catch{}</script>`;
const check = `<svg class="i-check" viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.2 4.2L19 7"/></svg>`;
const phone = (screen, alt, { cls = '', eager = false, hidden = false } = {}) => `<div class="phone ${cls}"${hidden ? ' aria-hidden="true"' : ''}><div class="device"><img src="${asset(`screens/${screen}.webp`)}" width="${W}" height="${H}" alt="${e(alt)}" ${eager ? 'fetchpriority="high"' : 'loading="lazy"'} decoding="async"><span class="glass" aria-hidden="true"></span></div></div>`;
const head = (eyebrow, heading, id, text = '', cls = '') => `<div class="section-head ${cls}"><p class="eyebrow">${e(eyebrow)}</p><h2 id="${id}">${rich(heading)}</h2>${text ? `<p class="lede">${e(text)}</p>` : ''}</div>`;
const checks = arr => `<ul class="checks">${arr.map(t => `<li>${check}<span>${e(t)}</span></li>`).join('')}</ul>`;
const badgeFor = site => (cls = '') => `<a class="store-badge ${cls}" href="${config.appStoreUrl}"><img src="${asset('img/app-store-badge.svg')}" width="156" height="52" alt="${e(site.ui.badgeAlt)}"></a>`;

// ---------------------------------------------------------------- layout
// `route` is the path below the locale prefix ('' for home, 'plus/'). Pages with `alternates` exist in every locale.
function layout(site, code, { title, description, body, route = '', type = 'home', noindex = false, alternates = false }) {
  const t = site.ui;
  const prefix = prefixOf(code);
  const home = `${base}${prefix}`;
  const url = `${origin}/${prefix}${route}`;
  const pill = (text, cls = '') => `<a class="pill ${cls}" href="${config.appStoreUrl}"><span>${e(text)}</span>${arrow}</a>`;
  const wordmark = `<a class="brand" href="${home}" aria-label="${e(t.home)}">${logoMark()}<span>Unpaged</span></a>`;
  const nav = [[t.nav[0], `${home}#library`], [t.nav[1], `${home}#moments`], [t.nav[2], `${home}#listening`], [t.nav[3], `${home}plus/`]];
  const links = alternates
    ? Object.keys(localeNames).map(c => `<link rel="alternate" hreflang="${htmlLang(c)}" href="${origin}/${prefixOf(c)}${route}">`).join('') + `<link rel="alternate" hreflang="x-default" href="${origin}/${route}">`
    : '';
  const languages = alternates
    ? `<details class="language"><summary><span class="sr">${e(t.language)}: </span>${e(localeNames[code])}</summary><div>${Object.entries(localeNames).map(([c, name]) => `<a href="${base}${prefixOf(c)}${route}" lang="${htmlLang(c)}" hreflang="${htmlLang(c)}"${c === code ? ' aria-current="page"' : ''}>${e(name)}</a>`).join('')}</div></details>`
    : '';
  return `<!doctype html><html lang="${htmlLang(code)}"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f3ed">
<title>${e(title)}</title><meta name="description" content="${e(description)}"><link rel="canonical" href="${url}">${links}
${noindex ? '<meta name="robots" content="noindex">' : ''}
<meta property="og:type" content="website"><meta property="og:site_name" content="Unpaged"><meta property="og:title" content="${e(title)}"><meta property="og:description" content="${e(description)}"><meta property="og:url" content="${url}"><meta property="og:image" content="${origin}/img/og.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="${e(t.ogAlt)}"><meta name="twitter:card" content="summary_large_image">
<meta name="apple-itunes-app" content="app-id=${config.appId}">
<link rel="icon" href="${asset('img/favicon.svg')}" type="image/svg+xml"><link rel="apple-touch-icon" href="${asset('img/apple-touch-icon.png')}">
<link rel="preload" href="${asset('fonts/newsreader.woff2')}" as="font" type="font/woff2" crossorigin>
<link rel="stylesheet" href="${asset('style.css')}"><link rel="stylesheet" href="${asset('sky.css')}">
${skyBoot}
<script>document.documentElement.classList.add('js');try{if(localStorage.getItem('unpaged-reduce-motion')==='1')document.documentElement.classList.add('reduce-motion')}catch{}</script>
${type === 'home' ? `<script type="application/ld+json">${JSON.stringify({ '@context': 'https://schema.org', '@type': 'MobileApplication', name: 'Unpaged', operatingSystem: 'iOS 18 or later', applicationCategory: 'MultimediaApplication', url, downloadUrl: config.appStoreUrl, offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD' }, author: { '@type': 'Person', name: 'Andrei Baluta' } })}</script>` : ''}
</head><body data-page="${type}">
<a class="skip-link" href="#main">${e(t.skip)}</a>
<header class="header"><div class="wrap header-inner">${wordmark}<nav aria-label="${e(t.primaryNav)}">${nav.map(([label, href], i) => `<a href="${href}"${type === 'plus' && i === 3 ? ' aria-current="page"' : ''}>${e(label)}</a>`).join('')}</nav>${pill(t.getApp, 'pill-small')}</div></header>
<main id="main" tabindex="-1">${type === 'doc' || type === '404' ? sky(true) : ''}${body}</main>
<footer class="footer"><div class="wrap footer-inner">${wordmark}<p>${e(site.footer.credit)}</p><nav aria-label="${e(t.legalNav)}">${site.footer.links.map(([label, slug]) => `<a href="${base}${slug}/">${e(label)}</a>`).join('')}</nav>${languages}<button type="button" class="motion-toggle" data-motion-toggle aria-pressed="false">${e(t.reduceMotion)}</button></div></footer>
<script type="module" src="${asset('app.mjs')}"></script><script type="module" src="${asset('sky.mjs')}"></script>
</body></html>`;
}

// ---------------------------------------------------------------- home
function homePage(site, code) {
  const t = site.ui, f = t.fields, badge = badgeFor(site);
  const home = `${base}${prefixOf(code)}`;

  const h = site.hero;
  const hero = `
<section class="hero" aria-labelledby="hero-title">${sky()}<div class="wrap hero-grid">
  <div class="hero-copy">
    <p class="eyebrow">${e(h.eyebrow)}</p>
    <h1 id="hero-title">${h.lines.map(l => `<span class="line">${rich(l)}</span>`).join('')}</h1>
    <p class="lede">${e(h.text)}</p>
    <div class="actions">${badge()}<a class="text-link" href="#anatomy">${e(h.secondary)}<span aria-hidden="true">↓</span></a></div>
    <ul class="facts">${h.facts.map(x => `<li>${e(x)}</li>`).join('')}</ul>
  </div>
  <figure class="hero-art">
    <div class="ribbon" aria-hidden="true"><span class="ribbon-body"></span><span class="ribbon-dot"></span></div>
    ${phone('library', h.alt, { cls: 'hero-phone', eager: true })}
    <div class="moment-chip" aria-hidden="true"><span class="chip-icon">${bookmarkGlyph}</span><span class="chip-text"><b>${e(h.chip.title)}</b><span>${e(h.chip.book)} · ${e(h.chip.time)}</span></span><span class="chip-ai">${sparkle}</span></div>
  </figure>
</div></section>`;

  const src = site.sources;
  const library = `
<section class="section library" id="library" aria-labelledby="library-title"><div class="wrap">
  <div class="library-top">${head(src.eyebrow, src.heading, 'library-title')}
  <div class="tabs" role="tablist" aria-label="${e(t.tabsLabel)}">${src.items.map((s, i) => `<button type="button" role="tab" id="tab-${i}" aria-controls="panel-${i}" aria-selected="${i === 0}" tabindex="${i ? -1 : 0}"><span class="tab-n">0${i + 1}</span>${e(s.name)}</button>`).join('')}</div></div>
  <div class="library-body">
    <div class="library-art"><div class="library-stack">${src.items.map((s, i) => phone(s.screen, s.alt, { cls: `lib-phone${i ? '' : ' is-active'}`, hidden: i > 0 })).join('')}</div></div>
    <div class="library-panels">${src.items.map((s, i) => `<div class="panel" role="tabpanel" id="panel-${i}" aria-labelledby="tab-${i}" tabindex="0" ${i ? 'hidden' : ''}><h3>${e(s.title)}</h3><p>${e(s.text)}</p>${checks(s.details)}</div>`).join('')}</div>
  </div>
</div></section>`;

  const m = site.moments;
  const moments = `
<section class="section moments" id="moments" aria-labelledby="moments-title"><div class="wrap moments-grid">
  <div class="moments-art">${phone('moments', m.alt, { cls: 'moments-phone' })}</div>
  <div class="moments-copy">${head(m.eyebrow, m.heading, 'moments-title', m.text)}
    <dl class="points">${m.points.map(([dt, dd]) => `<div><dt>${e(dt)}</dt><dd>${e(dd)}</dd></div>`).join('')}</dl>
  </div>
</div></section>`;

  // The anatomy stage: transcript tokens feed fields; app.mjs walks the seven steps.
  // The excerpt and the generated values stay in English, like the app.
  const a = site.anatomy, r = a.result;
  const stepOf = { listen: 1, transcribe: 2, name: 3, cat: 4, mood: 4, who: 5, quote: 6, note: 7 };
  const tokens = a.transcript.map(tok => {
    if (typeof tok === 'string') return e(tok);
    const [text, key, target] = tok;
    if (key === 'skip') return `<span class="t-skip">${e(text)}</span>`;
    return `<mark class="m" data-k="${key}" data-at="${stepOf[key]}" data-to="${target}">${e(text)}</mark>`;
  }).join('');
  // Deterministic waveform: a soft speech envelope, 96 bars.
  let seed = 7; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  const bars = Array.from({ length: 96 }, (_, i) => {
    const x = i * 6 + 1, amp = 6 + Math.round((0.35 + 0.65 * Math.abs(Math.sin(i * 0.37))) * rnd() * 22);
    const win = i >= 12 && i < 84; // 00:25 → 01:55 on a 00:10 → 02:10 strip
    return `<rect x="${x}" y="${30 - amp}" width="3" height="${amp * 2}" rx="1.5"${win ? ' class="w"' : ''}/>`;
  }).join('');
  const chips = (list, picked, prefix) => list.map(([id, label]) => `<span class="lab" id="${prefix}-${id}"${picked.includes(id) ? ' data-picked' : ''}>${e(label)}</span>`).join('');
  const field = (id, at, label, inner) => `<div class="field" id="${id}" data-at="${at}" data-state="done"><span class="f-label">${label}</span>${inner}</div>`;
  const anatomy = `
<section class="anatomy" id="anatomy" aria-labelledby="anatomy-title"><div class="wrap">
  ${head(a.eyebrow, a.heading, 'anatomy-title', a.text, 'anatomy-head')}
  <div class="anatomy-body" data-step="7">
    <ol class="steps">${a.steps.map((s, i) => `<li class="step" data-step="${i + 1}"><p class="step-label"><span>0${i + 1}</span>${e(s.label)}</p><h3>${e(s.title)}</h3><p>${e(s.text)}</p></li>`).join('')}</ol>
    <div class="stage" role="group" aria-label="${e(t.stageLabel)}">
      <div class="stage-nav" role="group" aria-label="${e(t.stepsLabel)}">${a.steps.map((s, i) => `<button type="button" data-go="${i + 1}" aria-label="${e(t.step)} ${i + 1}: ${e(s.label)}"><span>${i + 1}</span></button>`).join('')}<p class="stage-now" aria-live="polite" data-of="${e(t.of)}"></p></div>
      <div class="stage-grid">
        <div class="source">
          <div class="tape">
            <div class="tape-meta"><span lang="en">${e(a.book)} · ${e(a.chapter)}</span><span class="tape-tap">${bookmarkGlyph}${e(t.savedAt)} ${e(a.saved)}</span></div>
            <svg class="wave" viewBox="0 0 576 60" preserveAspectRatio="none" aria-hidden="true"><rect class="win" x="70" y="0" width="434" height="60" rx="6"/>${bars}<line class="head" x1="434" x2="434" y1="0" y2="60"/></svg>
            <div class="tape-scale" aria-hidden="true"><span>00:25</span><span>−75 s</span><span class="now">01:40</span><span>01:55</span></div>
          </div>
          <div class="transcript"><p class="t-status"><span class="t-dot"></span><span class="t-status-text">${e(t.transcript)}</span></p><p class="t-text" lang="en">${tokens}</p></div>
        </div>
        <div class="card" role="group" aria-label="${e(t.cardLabel)}">
          <div class="card-top"><span class="card-icon">${bookmarkGlyph}</span><span><b>${e(t.newMoment)}</b><span>${e(t.savedAt)} ${e(a.saved)}</span></span><span class="card-ai">${sparkle}Apple Intelligence</span></div>
          ${field('f-name', 3, e(f.name), `<p class="f-value f-title" lang="en" data-type>${e(r.name)}</p>`)}
          ${field('f-cats', 4, `${e(f.categories)} <i>${e(f.categoriesHint)}</i>`, `<div class="labs" lang="en">${chips(r.categories, r.picked, 'chip')}</div>`)}
          ${field('f-mood', 4, `${e(f.mood)} <i>${e(f.moodHint)}</i>`, `<div class="labs" lang="en">${chips(r.moods, [r.mood], 'mood')}</div>`)}
          ${field('f-who', 5, e(f.characters), `<div class="labs" lang="en">${r.characters.map(([id, n]) => `<span class="lab" id="${id}" data-picked>${e(n)}</span>`).join('')}</div>`)}
          ${field('f-quote', 6, `${e(f.quote)} <span class="verified">${check}${e(f.verified)}</span>`, `<p class="f-value f-quote" lang="en" data-type>“${e(r.quote)}”</p>`)}
          ${field('f-note', 7, e(f.note), `<p class="f-value" lang="en" data-type>${e(r.note)}</p>`)}
        </div>
      </div>
      <svg class="wires" aria-hidden="true"></svg>
    </div>
  </div>
  <div class="anatomy-foot"><p>${e(a.requires)}</p><p class="fine">${e(a.caption)}</p></div>
</div></section>`;

  const hb = site.habits;
  const habits = `
<section class="section habits" id="listening" aria-labelledby="habits-title"><div class="wrap habits-grid">
  ${head(hb.eyebrow, hb.heading, 'habits-title', hb.text, 'habits-head')}
  <div class="habit-row">${hb.items.map((it, i) => `<figure class="habit habit-${i}">${phone(it.screen, it.alt)}<figcaption><h3>${e(it.title)}${it.tag ? ` <span class="tag">${sparkle}${e(it.tag)}</span>` : ''}</h3><p>${e(it.text)}</p></figcaption></figure>`).join('')}</div>
</div></section>`;

  const icons = {
    chapters: '<path d="M4 6h12M4 12h12M4 18h8"/><path d="m16 15 5 3-5 3Z"/>',
    moon: '<path d="M19 15.5A8 8 0 0 1 8.5 5a8 8 0 1 0 10.5 10.5Z"/>',
    eq: '<path d="M6 4v16M12 4v16M18 4v16"/><path d="M3.5 14h5M9.5 8h5M15.5 12h5"/>',
    devices: '<rect x="3" y="5" width="13" height="10" rx="2"/><path d="M7 19h5"/><rect x="17" y="9" width="5" height="11" rx="1.5"/>'
  };
  const p = site.playback;
  const playback = `
<section class="section playback" aria-labelledby="playback-title"><div class="wrap playback-grid">
  <div class="playback-copy">${head(p.eyebrow, p.heading, 'playback-title', p.text)}
    <ul class="features">${p.items.map(([title, d, i]) => `<li><svg class="f-icon" viewBox="0 0 24 24" aria-hidden="true">${icons[i]}</svg><div><h3>${e(title)}</h3><p>${e(d)}</p></div></li>`).join('')}</ul>
  </div>
  <div class="playback-art">${phone('player', p.alts[0], { cls: 'pb-a' })}${phone('eq', p.alts[1], { cls: 'pb-b' })}</div>
</div></section>`;

  const pl = site.plus;
  const plus = `
<section class="section plus" aria-labelledby="plus-title"><div class="wrap plus-grid">
  <div>${head(pl.eyebrow, pl.heading, 'plus-title', pl.text)}<a class="text-link" href="${home}plus/">${e(pl.link)}${arrow}</a></div>
  <div class="plans">
    <div class="plan"><h3>Unpaged</h3><p class="plan-sub">${e(t.freePlan)}</p>${checks(pl.free)}</div>
    <div class="plan plan-plus"><h3>Unpaged <span class="tag">${sparkle}Plus</span></h3><p class="plan-sub">${e(t.plusPlan)}</p>${checks(pl.paid)}</div>
    <p class="fine plans-note">${e(pl.note)}</p>
  </div>
</div></section>`;

  return hero + library + moments + anatomy + habits + playback + plus + closing(site);
}

function closing(site) {
  const c = site.close;
  return `
<section class="closing" aria-labelledby="close-title"><div class="wrap closing-inner">
  <img class="closing-icon" src="${asset('img/icon-512.webp')}" width="512" height="512" alt="${e(site.ui.iconAlt)}" loading="lazy">
  <p class="eyebrow">${e(c.eyebrow)}</p><h2 id="close-title">${rich(c.title)}</h2><p class="lede">${e(c.text)}</p>${badgeFor(site)('badge-light')}
</div></section>`;
}

const pIcons = {
  sparkles: sparkle,
  recap: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12a8 8 0 1 0 2.4-5.7"/><path d="M4 4v4h4"/><path d="M12 8v4l3 2"/></svg>',
  cloud: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 18h10.5a4 4 0 0 0 .4-8A6 6 0 0 0 6.3 9.2 4.5 4.5 0 0 0 7 18Z"/></svg>',
  plans: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 10h18"/></svg>'
};
function plusPage(site, code) {
  const t = site.ui, pp = site.plusPage, r = site.anatomy.result;
  const label = id => r.categories.concat(r.moods).find(([k]) => k === id)[1];
  return `
<section class="plus-hero">${sky()}<div class="wrap plus-hero-grid">
  <div><a class="text-link back" href="${base}${prefixOf(code)}">← ${e(t.back)}</a><p class="eyebrow">${e(pp.eyebrow)}</p><h1>${rich(pp.heading)}</h1><p class="lede">${e(pp.intro)}</p><div class="actions">${badgeFor(site)()}</div></div>
  <div class="plus-art">${phone('recap', site.habits.items[1].alt, { eager: true })}<div class="moment-chip chip-static" aria-hidden="true"><span class="chip-icon">${bookmarkGlyph}</span><span class="chip-text"><b>${e(r.name)}</b><span>${[r.picked[0], r.picked[2], r.mood].map(label).join(' · ')}</span></span><span class="chip-ai">${sparkle}</span></div></div>
</div></section>
<section class="section plus-details" aria-label="${e(t.plusIncludes)}"><div class="wrap details-grid">${pp.details.map(([i, title, d]) => `<article><span class="d-icon">${pIcons[i]}</span><h2>${e(title)}</h2><p>${e(d)}</p></article>`).join('')}</div>
<div class="wrap"><p class="fine qual">${e(pp.qualification)}</p></div></section>
${closing(site)}`;
}

for (const [code, site] of Object.entries(locales)) {
  const prefix = prefixOf(code);
  write(`${prefix}index.html`, layout(site, code, { title: site.title, description: site.description, body: homePage(site, code), alternates: true }));
  write(`${prefix}plus/index.html`, layout(site, code, { title: site.plusPage.title, description: site.plusPage.description, body: plusPage(site, code), route: 'plus/', type: 'plus', alternates: true }));
}

// GitHub Pages serves the root 404 for every unknown URL. Each locale's full page (header, body, footer)
// ships as a template; a locale prefix in the path swaps it in before app.mjs runs.
const missingBody = (site, code) => `<section class="lost"><div class="wrap lost-inner"><div class="lost-ribbon" aria-hidden="true"><span class="ribbon-body"></span><span class="ribbon-dot"></span></div><p class="eyebrow">404</p><h1 id="lost-title">${rich(site.notFound.heading)}</h1><p class="lede">${e(site.notFound.text)}</p><a class="pill" href="${base}${prefixOf(code)}"><span>${e(site.notFound.cta)}</span>${arrow}</a></div></section>`;
const page404 = (site, code) => layout(site, code, { title: site.notFound.title, description: site.notFound.text, body: missingBody(site, code), route: '404.html', type: '404', noindex: true });
const chrome = html => html.slice(html.indexOf('<a class="skip-link"'), html.indexOf('<script type="module"'));
const lost = Object.fromEntries(Object.entries(locales).filter(([c]) => c !== 'en').map(([c, s]) => [c, { lang: htmlLang(c), title: s.notFound.title, text: s.notFound.text }]));
const templates = Object.keys(lost).map(c => `<template id="lost-${c}">${chrome(page404(locales[c], c))}</template>`).join('');
const swap = `${templates}<script>{const c=location.pathname.slice(${base.length}).split('/')[0],s=${JSON.stringify(lost)}[c],t=document.getElementById('lost-'+c);
if(s&&t){const d=document,n=t.content;d.documentElement.lang=s.lang;d.title=s.title;for(const m of d.querySelectorAll('meta[name=description],meta[property="og:description"]'))m.content=s.text;d.querySelector('meta[property="og:title"]').content=s.title;
for(const q of ['.skip-link','header','main','footer'])d.querySelector(q).replaceWith(n.querySelector(q));}
for(const x of document.querySelectorAll('template[id^=lost-]'))x.remove();}</script>`;
write('404.html', page404(english, 'en').replace('<script type="module"', `${swap}\n<script type="module"`));

// ---------------------------------------------------------------- documents
const DOCS = [
  { file: 'support.md', path: 'support/', label: 'Support', description: 'Help for Unpaged, the audiobook player for iPhone: importing books, free LibriVox classics, Audiobookshelf, AI features, iCloud Sync and purchases.' },
  { file: 'privacy-policy.md', path: 'privacy/', label: 'Privacy Policy', description: 'How Unpaged handles your data: no account, no analytics or tracking, and no developer server.' },
  { file: 'EULA.md', path: 'terms/', label: 'Terms of Use', description: 'The end user license agreement for Unpaged, including the Unpaged Plus subscription terms.' }
];
// Old public URLs that now have a page on this site.
const LINK_REWRITES = { 'https://gist.github.com/andreibalu/aca2af2e2176cc453175f708b2481262': 'privacy/' };

// Covers exactly what the three documents use: #/##/### headings, paragraphs, **bold**,
// *italic*/_italic_, `code`, [links](url), <autolinks>, nested ordered/unordered lists, and pipe tables.
function inline(text, ctx) {
  const slots = [];
  const hold = html => `\u0000${slots.push(html) - 1}\u0000`;
  let s = text
    .replace(/`([^`]+)`/g, (_, code) => hold(`<code>${e(code)}</code>`))
    .replace(/<(https?:\/\/[^>\s]+)>/g, (_, url) => { const { href, label } = ctx.link(url); return hold(`<a href="${e(href)}">${e(label)}</a>`); })
    .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_, label, url) => hold(`<a href="${e(ctx.link(url).href)}">${inline(label, ctx)}</a>`));
  s = e(s)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[^\w*])\*(?!\s)(.+?)\*(?!\w)/g, '$1<em>$2</em>')
    .replace(/(^|[^\w])_(?!\s)(.+?)_(?!\w)/g, '$1<em>$2</em>');
  return s.replace(/\u0000(\d+)\u0000/g, (_, i) => slots[+i]);
}
const plain = s => s.replace(/[*_`]/g, '').replace(/\[([^\]]+)\]\([^)]+\)/g, '$1');
const LIST = /^(\s*)([-*]|\d+\.)\s+(.*)$/;
const indentOf = line => line.match(/^\s*/)[0].length;
const isBlank = line => line.trim() === '';
const isTableStart = (lines, i) => /^\s*\|/.test(lines[i]) && i + 1 < lines.length && /^\s*\|?\s*:?-{3,}/.test(lines[i + 1]);

function markdown(md, ctx) {
  const lines = md.replace(/\r\n?/g, '\n').split('\n');
  const html = [], headings = [], used = new Set();
  const slug = text => {
    const b = plain(text).toLowerCase().normalize('NFKD').replace(/[^\w\s-]/g, '').trim().replace(/\s+/g, '-') || 'section';
    let id = b;
    for (let n = 2; used.has(id); n++) id = `${b}-${n}`;
    used.add(id);
    return id;
  };
  function list(i, indent) {
    const ordered = /\d/.test(lines[i].match(LIST)[2]);
    const items = [];
    while (i < lines.length) {
      const line = lines[i];
      if (isBlank(line)) {
        let j = i + 1;
        while (j < lines.length && isBlank(lines[j])) j++;
        const m = lines[j]?.match(LIST);
        if (m && m[1].length === indent && /\d/.test(m[2]) === ordered) { i = j; continue; }
        if (m && m[1].length > indent && items.length) { i = j; continue; }
        break;
      }
      const m = line.match(LIST);
      if (m && m[1].length === indent) { items.push({ text: m[3], children: [] }); i++; continue; }
      if (m && m[1].length > indent && items.length) { const nested = list(i, m[1].length); items.at(-1).children.push(nested.html); i = nested.i; continue; }
      if (!m && indentOf(line) > indent && items.length) { items.at(-1).text += ' ' + line.trim(); i++; continue; }
      break;
    }
    const tag = ordered ? 'ol' : 'ul';
    return { html: `<${tag}>\n${items.map(it => `<li>${inline(it.text, ctx)}${it.children.join('')}</li>`).join('\n')}\n</${tag}>`, i };
  }
  function table(i) {
    const cells = row => row.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(c => c.trim());
    const headRow = cells(lines[i]);
    i += 2;
    const rows = [];
    while (i < lines.length && /^\s*\|/.test(lines[i])) rows.push(cells(lines[i++]));
    const th = headRow.map(x => `<th scope="col">${inline(x, ctx)}</th>`).join('');
    const tr = rows.map(row => `<tr>${row.map((c, k) => `<td data-label="${e(plain(headRow[k] ?? ''))}">${inline(c, ctx)}</td>`).join('')}</tr>`).join('\n');
    return { html: `<table>\n<thead><tr>${th}</tr></thead>\n<tbody>\n${tr}\n</tbody>\n</table>`, i };
  }
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (isBlank(line)) { i++; continue; }
    const h = line.match(/^(#{1,3})\s+(.*)$/);
    if (h) {
      const level = h[1].length, text = h[2].trim();
      if (level === 1) html.push(`<h1>${inline(text, ctx)}</h1>`);
      else { const id = slug(text); headings.push({ level, id, text: plain(text) }); html.push(`<h${level} id="${id}">${inline(text, ctx)}</h${level}>`); }
      i++; continue;
    }
    if (isTableStart(lines, i)) { const tb = table(i); html.push(tb.html); i = tb.i; continue; }
    const m = line.match(LIST);
    if (m) { const l = list(i, m[1].length); html.push(l.html); i = l.i; continue; }
    const para = [];
    while (i < lines.length && !isBlank(lines[i]) && !/^#{1,3}\s/.test(lines[i]) && !LIST.test(lines[i]) && !isTableStart(lines, i)) para.push(lines[i++].trim());
    if (para.length === 1 && /^_[^_]+_$/.test(para[0])) html.push(`<p class="updated">${inline(para[0], ctx)}</p>`);
    else if (para.length > 1 && para.every(l => l.startsWith('**'))) html.push(`<p class="meta">${para.map(l => inline(l, ctx)).join('<br>\n')}</p>`);
    else if (para.length > 1 && para.every(l => l.length < 60)) html.push(`<p>${para.map(l => inline(l, ctx)).join('<br>\n')}</p>`); // a postal address keeps its breaks
    else html.push(`<p>${inline(para.join(' '), ctx)}</p>`);
  }
  return { html: html.join('\n'), headings, title: plain((md.match(/^#\s+(.*)$/m) || [, 'Unpaged'])[1]) };
}
function toc(headings) {
  const hasH3 = headings.some(h => h.level === 3);
  let html = '', open = false;
  for (const h of headings) {
    if (h.level === 2) {
      if (open) { html += '</ul></li>'; open = false; } else if (html) html += '</li>';
      html += `<li><a href="#${h.id}">${e(h.text)}</a>`;
    } else if (hasH3) {
      if (!open) { html += '<ul>'; open = true; }
      html += `<li><a href="#${h.id}">${e(h.text)}</a></li>`;
    }
  }
  html += open ? '</ul></li>' : '</li>';
  return `<nav aria-label="On this page"><details class="toc"${hasH3 ? '' : ' open'}><summary>On this page</summary><ul>${html}</ul></details></nav>`;
}
for (const doc of DOCS) {
  const md = fs.readFileSync(path.join(repo, doc.file), 'utf8');
  const ctx = { link(url) { const target = LINK_REWRITES[url]; return target ? { href: base + target, label: `${origin}/${target}` } : { href: url, label: url }; } };
  const { html, headings, title } = markdown(md, ctx);
  const firstH2 = html.indexOf('<h2');
  const withToc = firstH2 < 0 ? html : html.slice(0, firstH2) + toc(headings) + '\n' + html.slice(firstH2);
  const others = DOCS.filter(d => d !== doc).map(d => `<a href="${base}${d.path}">${d.label}</a>`).join(' · ');
  const body = `<article class="doc"><div class="wrap doc-wrap"><div class="doc-body">\n${withToc}\n</div><p class="doc-foot">See also: ${others}</p></div></article>`;
  write(`${doc.path}index.html`, layout(english, 'en', { title: `${title.replace(/^Unpaged\s+—\s+/, '')} · Unpaged`, description: doc.description, body, route: doc.path, type: 'doc' }));
}

// ---------------------------------------------------------------- crawl files
const pages = [...Object.keys(locales).flatMap(c => [prefixOf(c), `${prefixOf(c)}plus/`]), ...DOCS.map(d => d.path)];
fs.writeFileSync(path.join(out, 'sitemap.xml'), `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${pages.map(p => `  <url><loc>${origin}/${p}</loc></url>`).join('\n')}\n</urlset>\n`);
fs.writeFileSync(path.join(out, 'robots.txt'), `User-agent: *\nAllow: /\n\nSitemap: ${origin}/sitemap.xml\n`);
fs.writeFileSync(path.join(out, '.nojekyll'), '');

// ---------------------------------------------------------------- link check
// Every local href/src must resolve to a file in dist/, and every #fragment must exist on its target page.
let broken = 0;
const idsOf = file => new Set([...fs.readFileSync(file, 'utf8').matchAll(/\sid="([^"]+)"/g)].map(m => m[1]));
for (const file of written) {
  const html = fs.readFileSync(file, 'utf8');
  for (const [, attr, ref] of html.matchAll(/\s(href|src)="([^"]+)"/g)) {
    if (/^(https?:|mailto:|data:)/.test(ref)) continue;
    const [refPath, frag] = ref.split('#');
    let target = refPath ? (refPath.startsWith('/') ? path.join(out, refPath.slice(base.length - 1)) : path.resolve(path.dirname(file), refPath)) : file;
    if (refPath && refPath.endsWith('/')) target = path.join(target, 'index.html');
    const rel = path.relative(out, file);
    if (!fs.existsSync(target)) { console.error(`broken ${attr} in ${rel}: ${ref}`); broken++; continue; }
    if (frag && !idsOf(target).has(frag)) { console.error(`missing #${frag} in ${rel}: ${ref}`); broken++; }
  }
}
if (broken) { console.error(`${broken} broken link(s)`); process.exit(1); }
console.log(`Built ${written.length} pages into ${path.relative(process.cwd(), out) || '.'} for ${origin}/ — links OK`);
